package launchdarkly

import (
	"context"
	"fmt"
	"net/http"
	"net/url"
	"strings"
)

// The default-release-plan endpoints are beta and not generated by
// api-client-go v25.2.0, so they share the raw HTTP transport in
// environment_release_plan_helper.go.

type environmentDefaultReleasePlanPutRequest struct {
	Key string `json:"key"`
}

func environmentDefaultReleasePlanEndpoint(apiHost, projectKey, envKey string) string {
	host := apiHost
	if host == "" {
		host = DEFAULT_LAUNCHDARKLY_HOST
	}
	p := fmt.Sprintf("/api/v2/projects/%s/environments/%s/default-release-plan", url.PathEscape(projectKey), url.PathEscape(envKey))
	if u, err := url.Parse(host); err == nil && u.Scheme != "" {
		u.Path = p
		return u.String()
	}
	return fmt.Sprintf("https://%s%s", host, p)
}

// getEnvironmentDefaultReleasePlan returns the environment's default release
// plan, or a nil plan when the API answers 204 because none is set.
func getEnvironmentDefaultReleasePlan(ctx context.Context, client *Client, projectKey, envKey string) (*environmentReleasePlanRep, *http.Response, error) {
	var plan environmentReleasePlanRep
	endpoint := environmentDefaultReleasePlanEndpoint(client.apiHost, projectKey, envKey)
	res, err := doEnvironmentReleasePlanRequest(ctx, client, http.MethodGet, endpoint, nil, &plan)
	if err != nil {
		return nil, res, err
	}
	if res.StatusCode == http.StatusNoContent {
		return nil, res, nil
	}
	return &plan, res, nil
}

func setEnvironmentDefaultReleasePlan(ctx context.Context, client *Client, projectKey, envKey, planKey string) error {
	endpoint := environmentDefaultReleasePlanEndpoint(client.apiHost, projectKey, envKey)
	body := environmentDefaultReleasePlanPutRequest{Key: planKey}
	_, err := doEnvironmentReleasePlanRequest(ctx, client, http.MethodPut, endpoint, body, nil)
	return err
}

func clearEnvironmentDefaultReleasePlan(ctx context.Context, client *Client, projectKey, envKey string) (*http.Response, error) {
	endpoint := environmentDefaultReleasePlanEndpoint(client.apiHost, projectKey, envKey)
	return doEnvironmentReleasePlanRequest(ctx, client, http.MethodDelete, endpoint, nil, nil)
}

func environmentDefaultReleasePlanID(projectKey, envKey string) string {
	return projectKey + "/" + envKey
}

// environmentDefaultReleasePlanIdToKeys splits a composite ID of the form
// `project_key/environment_key`.
func environmentDefaultReleasePlanIdToKeys(id string) (projectKey, envKey string, err error) {
	parts := strings.Split(id, "/")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return "", "", fmt.Errorf("found unexpected environment default release plan id format: %q expected format: 'project_key/environment_key'", id)
	}
	return parts[0], parts[1], nil
}
